  'meta.home.title': 'Hevalo — Bi hevalên xwe re fêrî kurdî bibe',
  'meta.about.title': 'Derbarê Hevalo de — kurdî, bi hev re',
  'meta.about.description': 'Çima Hevalo heye, îro çi dike û paşê çi tê: cihek ji bo fêrbûna kurdî, pêşî kurmancî, bi lîstik, heval û civakê.',
  'meta.privacy.title': 'Nihênî · Hevalo',
  'meta.privacy.description': 'Hevalo çi tomar dike, çima, û biryara çi di destê te de ye. Reklam tune, şopandin di sepan û malperên din de tune, û daneyên te tu caran nayên firotin.',
  'meta.terms.title': 'Merc · Hevalo',
  'meta.terms.description': 'Rêzikên Hevalo bi zimanekî sade: hesabê te, tu çawa bi kesên din re tevdigerî, tiştên ku tu diweşînî, û Zêr û gewher çawa dixebitin.',
