  'landing.hero.title1': 'Fêrî kurdî bibe.',
  'landing.hero.title2': 'Bi hev re bilîzin.',
  'landing.hero.lead':
    'Waneyên kurt, paşê lîstikên peyvan ên ku tu tê de tiştê ku nû hîn bûyî li hember hevalên xwe bi kar tînî. Em bi kurmancî dest pê dikin.',
  'landing.hero.start': 'Dest bi fêrbûna kurdî bike',
  'landing.hero.play': 'Li lîstikan binêre',
  'landing.hero.note': 'Bêpere · Di geroka te de dixebite · Sepanên iOS û Android di rê de ne',
