  'landing.gloss.howAreYou': 'How are you?',
  'landing.mock.battleLabel': 'Pêşbaziya Peyvan li Hevalo: tu û Rojîn pêşbaziyê dikin ka kî pêşî heman peyva kurdî dibîne, û tu di sê hewldanan de dibînî. Peyv heval e.',
  'landing.mock.leagueLabel': 'Di Lîga Zêrîn a vê hefteyê de cihê duyem, bi 298 XP.',
  'landing.mock.wordLabel': 'Peyveke nû: heval, bi îngilîzî friend.',
  'landing.mock.inviteLabel': 'Rojîn di peyamekê de vexwendineke Pêşbaziya Peyvan ji te re dişîne, bi bişkokeke ji bo tevlîbûnê.',
  'landing.mock.boardLabel': 'XP-ya vê hefteyê di nav hevalan de: Rojîn yekem, tu duyem, Dilan sêyem.',
  'landing.mock.lessonLabel': 'Rahênaneke waneyê: hevoka “Îro çi roj e?”, nîşaneke ku roj bi îngilîzî day e, û bersiva rast hatiye hilbijartin.',
  'landing.mock.pathLabel': 'Rêya fêrbûnê di sepana Hevalo de: beşa 1, Silav, waneya yekem qediyaye, ya din amade ye ku dest pê bike, û Hevalo li kêleka wê radiweste.',
  'landing.mock.storiesLabel': 'Pirtûkxaneya çîrokan di sepana Hevalo de: te çiqas xwendiye, çîrokek ku te nîvê wê xwendiye, û çîrokên bijartî.',
  'landing.screens.label': 'Dîmenên sepana Hevalo',
  'landing.mock.progressLabel': 'Profîla Dilan li asta 12 bi paşxaneyeke daristanê, rêza lîgên heftane li ser Zêrîn, û xelateke rojane ya 20 Zêr.',
